"""Curated gap discovery; writes briefs only to the existing canonical store.

Not a permutation generator. Re-running preserves all existing decisions.
"""
import json
from pathlib import Path
from datetime import date


from pathlib import Path as _GenerationPath
import json as _generation_json
_control = _GenerationPath(__file__).resolve().parents[1] / "content/editorial/generation-control.json"
if _control.exists() and _generation_json.loads(_control.read_text()).get("status") == "PAUSED_FOR_LAUNCH":
    raise SystemExit("Content generation is PAUSED_FOR_LAUNCH. Resume only after an explicit user instruction.")

store = Path('content/editorial/first-500-inventory.json')
briefs = json.loads(store.read_text())
baseline = json.loads(Path('docs/existing-content-semantic-map.json').read_text())['pages']
assert baseline and len({page["path"] for page in baseline}) == len(baseline)
for i, brief in enumerate(briefs[:500], 1):
    brief.setdefault('id', f'SVD-FIRST-{i:04d}')
    brief.setdefault('batch', 'first-500')

