already = {b['path'] for b in briefs}
family_codes = {'comparison':'CMP','captions':'CAP','formats':'FMT','troubleshooting':'TRB','codecs':'COD','audio':'AUD','glossary':'GLS','browser':'BRW','device':'DEV','creator':'CRT','copyright':'PRV','faq':'FAQ','platform-help':'PLT','how-to':'HLP'}
for family, slug, title, benefit, gap in gaps:
    platform = next((p for p in ['youtube','facebook','instagram','tiktok','snapchat','whatsapp'] if slug.startswith(p+'-')), 'general')
    if slug.startswith('spotlight-'): platform='snapchat'
    path=f'/guides/{platform}/{slug}/'
    if path in already: continue
    count=sum(b.get('batch')=='expansion-2026-10' and b['platform']==platform and b['family']==family for b in briefs)+1
    identifier=f'SVD-{platform.upper()[:3]}-{family_codes[family]}-{count:04d}'
    tools={'general':'/youtube-video-downloader/','youtube':'/youtube-video-downloader/','facebook':'/facebook-video-downloader/','instagram':'/instagram-video-downloader/','tiktok':'/tiktok-video-downloader/','snapchat':'/snapchat-spotlight-downloader/','whatsapp':None}
    hubs={'general':'/youtube/','youtube':'/youtube/','facebook':'/facebook/','instagram':'/instagram/','tiktok':'/tiktok/','snapchat':'/snapchat-downloader/','whatsapp':'/guides/'}
    words=set((title+' '+benefit).lower().replace(':',' ').split())
    closest=sorted(baseline,key=lambda p:len(words&set((p['title']+' '+p['answerEvidence']).lower().split())),reverse=True)[:3]
    disposition={'classification':'NEEDS_RESEARCH','destination':path,'reason':gap+' Source-specific research, semantic review and editorial approval are required before writing.','reviewedAt':str(date.today()),'targetUser':'A viewer or authorized creator trying to '+benefit[0].lower()+benefit[1:],'primaryQuestion':title,'internalLinkDestination':closest[0]['path'],'outcome':'RESEARCH_REQUIRED'}
    if slug=='spotlight-profile-vs-clip':
        destination='/guides/snapchat/snapchat-spotlight-copy-direct-link/'
        disposition.update(classification='MERGE_WITH_EXISTING',destination=destination,internalLinkDestination=destination,reason=gap,outcome='CONSOLIDATED')
    briefs.append({'id':identifier,'batch':'expansion-2026-10','path':path,'canonical':path,'platform':platform,'family':family,'cluster':family,'title':title,'h1':title,'description':benefit+' Check the relevant evidence and limitations before choosing a video workflow.','primaryKeyword':title,'secondaryKeywords':[slug.replace('-',' '),benefit],'intent':'task:'+slug,'targetUser':disposition['targetUser'],'userProblem':title,'userBenefit':benefit,'whyExistingContentDoesNotSatisfy':gap,'closestExistingPages':[p['path'] for p in closest],'semanticReview':{'state':'GAP_IDENTIFIED_RESEARCH_PENDING','comparisons':[f'Current {len(baseline)}-page answer/heading map','Other curated candidate tasks'],'expectedSERP':'Intent hypothesis only; no observed SERP equivalence or search-volume claim'},'priority':1 if family in ('captions','formats','troubleshooting','glossary') else 2,'targetDownloader':tools[platform],'hub':hubs[platform],'related':[p['path'] for p in closest if p['type']=='article'][:3],'status':'ARCHIVED' if disposition['classification']=='MERGE_WITH_EXISTING' else 'DRAFT','indexable':False,'inventoryApproval':None,'disposition':disposition})
    if platform == 'whatsapp': briefs[-1]['contentRole']='education'
    already.add(path)
store.write_text(json.dumps(briefs,indent=2)+'\n')
print('Original 500 preserved; curated expansion candidates:',len(briefs)-500)
